import { test, expect } from '@playwright/test';

test.describe('Logo Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should navigate to home page when clicking the logo', async ({ page }) => {
    // Navigate to a different page first
    await page.goto('https://example.com/about');

    // Click the logo to navigate back to home
    const logo = page.getByRole('link', { name: /logo/i });
    await logo.click();

    // Verify we're on the home page
    await expect(page).toHaveURL('https://example.com/');
  });

  test('should display the logo on the home page', async ({ page }) => {
    // Verify the logo is visible on the home page
    const logo = page.getByRole('link', { name: /logo/i });
    await expect(logo).toBeVisible();
  });

  test('should navigate to home page from multiple pages via logo click', async ({ page }) => {
    // Test from about page
    await page.goto('https://example.com/about');
    let logo = page.getByRole('link', { name: /logo/i });
    await logo.click();
    await expect(page).toHaveURL('https://example.com/');

    // Test from contact page
    await page.goto('https://example.com/contact');
    logo = page.getByRole('link', { name: /logo/i });
    await logo.click();
    await expect(page).toHaveURL('https://example.com/');
  });
});
